1	package custody
2	
3	import (
4		"encoding/json"
5		"fmt"
6		"os"
7		"path/filepath"
8		"strings"
9		"sync"
10		"time"
11	)
12	
13	// Store 是一份本地样品数据的入口。零值不可用，请通过 Open 创建或重新打开。
14	//
15	// 同一时刻所有读写操作都由一把互斥锁串行化，因此并发操作同一样品时，
16	// 既不会超量分装，也不会出现两条待确认交接。每次成功的写操作都会
17	// 原子落盘（临时文件 + rename），关闭后重新打开同一文件即可恢复
18	// 全部样品、保管历史以及交接编号的重复提交判断。
19	type Store struct {
20		path string
21		mu   sync.Mutex
22		data *ledger
23	
24		// now 可在同包测试中替换，便于确定性地控制事件时间。
25		now func() time.Time
26	}
27	
28	// Open 打开 path 指向的本地样品数据：文件不存在时创建一份新数据，
29	// 已存在时原样重新打开，历史记录与交接编号判断继续有效。
30	func Open(path string) (*Store, error) {
31		if strings.TrimSpace(path) == "" {
32			return nil, fmt.Errorf("%w: 数据文件路径不能为空", ErrInvalid)
33		}
34	
35		s := &Store{path: path, now: time.Now}
36	
37		raw, err := os.ReadFile(path)
38		switch {
39		case err == nil:
40			var l ledger
41			if err := json.Unmarshal(raw, &l); err != nil {
42				return nil, fmt.Errorf("读取本地样品数据 %s 失败: %w", path, err)
43			}
44			if l.Version != 1 {
45				return nil, fmt.Errorf("本地样品数据 %s 的版本 %d 不受支持", path, l.Version)
46			}
47			if l.Samples == nil {
48				l.Samples = make(map[string]*sampleRecord)
49			}
50			if l.Transfers == nil {
51				l.Transfers = make(map[string]*transferRecord)
52			}
53			s.data = &l
54		case os.IsNotExist(err):
55			s.data = newLedger()
56			if err := s.persist(s.data); err != nil {
57				return nil, err
58			}
59		default:
60			return nil, fmt.Errorf("打开本地样品数据 %s 失败: %w", path, err)
61		}
62		return s, nil
63	}
64	
65	// persist 把整份状态原子写入文件：先写同目录临时文件，再 rename 覆盖，
66	// 避免进程中断留下半截数据。
67	func (s *Store) persist(l *ledger) error {
68		raw, err := json.MarshalIndent(l, "", "  ")
69		if err != nil {
70			return fmt.Errorf("编码本地样品数据失败: %w", err)
71		}
72	
73		dir := filepath.Dir(s.path)
74		tmp, err := os.CreateTemp(dir, ".custody-*.tmp")
75		if err != nil {
76			return fmt.Errorf("创建临时数据文件失败: %w", err)
77		}
78		tmpName := tmp.Name()
79		defer os.Remove(tmpName)
80	
81		if _, err := tmp.Write(raw); err != nil {
82			tmp.Close()
83			return fmt.Errorf("写入临时数据文件失败: %w", err)
84		}
85		if err := tmp.Close(); err != nil {
86			return fmt.Errorf("关闭临时数据文件失败: %w", err)
87		}
88		if err := os.Rename(tmpName, s.path); err != nil {
89			return fmt.Errorf("替换本地样品数据文件失败: %w", err)
90		}
91		return nil
92	}
93	
94	// commit 在候选状态上落盘并替换内存状态。调用方必须保证 candidate
95	// 已通过全部校验；落盘失败时内存状态保持不变。
96	func (s *Store) commit(candidate *ledger) error {
97		if err := s.persist(candidate); err != nil {
98			return err
99		}
100		s.data = candidate
101		return nil
102	}
103	
104	// RegisterInput 是登记原样的入参。
105	type RegisterInput struct {
106		// ID 为样品编号，在这份数据内唯一，去空白后非空。
107		ID string
108		// Qty 为初始数量（毫升），大于零、最多三位小数的十进制字符串。
109		Qty string
110		// Holder 为初始持有人，去空白后非空。
111		Holder string
112		// Location 为初始地点，去空白后非空。
113		Location string
114	}
115	
116	// Register 登记一份原样。编号重复等冲突返回包装了 ErrConflict 的错误，
117	// 且不会写入任何记录。
118	func (s *Store) Register(in RegisterInput) (*Sample, error) {
119		s.mu.Lock()
120		defer s.mu.Unlock()
121	
122		id, err := trimRequired("样品编号", in.ID)
123		if err != nil {
124			return nil, err
125		}
126		holder, err := trimRequired("持有人", in.Holder)
127		if err != nil {
128			return nil, err
129		}
130		location, err := trimRequired("地点", in.Location)
131		if err != nil {
132			return nil, err
133		}
134		qty, err := parseQuantity(in.Qty)
135		if err != nil {
136			return nil, err
137		}
138		if _, exists := s.data.Samples[id]; exists {
139			return nil, fmt.Errorf("%w: 样品编号 %q 已存在", ErrConflict, id)
140		}
141	
142		candidate := s.data.deepCopy()
143		now := s.now().UTC()
144		candidate.Samples[id] = &sampleRecord{
145			ID:        id,
146			Initial:   qty,
147			Remaining: qty,
148			Holder:    holder,
149			Location:  location,
150			Children:  []string{},
151			History: []historyRecord{{
152				Kind:     "register",
153				Time:     now,
154				Holder:   holder,
155				Location: location,
156				Detail:   "登记原样",
157			}},
158		}
159		if err := s.commit(candidate); err != nil {
160			return nil, err
161		}
162		return buildSampleView(candidate.Samples[id], candidate), nil
163	}
164	
165	// SplitPart 是一次分装中的一个子样。
166	type SplitPart struct {
167		// ID 为子样编号，在这份数据内唯一，去空白后非空。
168		ID string
169		// Qty 为该子样数量（毫升），大于零、最多三位小数。
170		Qty string
171	}
172	
173	// SplitInput 是一次分装的入参；一次分装可以同时创建多个子样。
174	type SplitInput struct {
175		// ParentID 为来源样品编号。
176		ParentID string
177		// Parts 为本次要创建的全部子样，至少一个。
178		Parts []SplitPart
179	}
180	
181	// Split 执行一次原子分装。任一子样编号重复、数量不合法或子样总量超过
182	// 来源样品剩余量时，整次分装都不生效。成功后来源样品按整数刻度精确
183	// 扣减，子样继承当时的持有人和地点，并可继续分装。
184	//
185	// 返回来源样品的最新视图；子样可通过 GetSample 分别查询。
186	func (s *Store) Split(in SplitInput) (*Sample, error) {
187		s.mu.Lock()
188		defer s.mu.Unlock()
189	
190		parentID, err := trimRequired("来源样品编号", in.ParentID)
191		if err != nil {
192			return nil, err
193		}
194		if len(in.Parts) == 0 {
195			return nil, fmt.Errorf("%w: 一次分装至少要创建一个子样", ErrInvalid)
196		}
197	
198		parent, ok := s.data.Samples[parentID]
199		if !ok {
200			return nil, fmt.Errorf("%w: 来源样品 %q 不存在", ErrNotFound, parentID)
201		}
202	
203		// 先在局部完成全部校验，任何一项不通过都直接返回，不动状态。
204		type parsedPart struct {
205			id  string
206			qty int64
207		}
208		parsed := make([]parsedPart, 0, len(in.Parts))
209		seen := make(map[string]struct{}, len(in.Parts))
210		var total int64
211		for _, p := range in.Parts {
212			id, err := trimRequired("子样编号", p.ID)
213			if err != nil {
214				return nil, err
215			}
216			if _, dup := seen[id]; dup {
217				return nil, fmt.Errorf("%w: 本次分装中子样编号 %q 重复", ErrInvalid, id)
218			}
219			if _, exists := s.data.Samples[id]; exists {
220				return nil, fmt.Errorf("%w: 子样编号 %q 已存在", ErrConflict, id)
221			}
222			if id == parentID {
223				return nil, fmt.Errorf("%w: 子样编号 %q 不能与来源样品相同", ErrInvalid, id)
224			}
225			qty, err := parseQuantity(p.Qty)
226			if err != nil {
227				return nil, err
228			}
229			seen[id] = struct{}{}
230			parsed = append(parsed, parsedPart{id: id, qty: qty})
231			total += qty
232			if total < 0 {
233				return nil, fmt.Errorf("%w: 子样总量超出可表示范围", ErrInvalid)
234			}
235		}
236	
237		if parent.PendingID != "" {
238			return nil, fmt.Errorf("%w: 样品 %q 存在待确认交接 %s，不能分装",
239				ErrConflict, parentID, parent.PendingID)
240		}
241		if parent.Remaining == 0 {
242			return nil, fmt.Errorf("%w: 样品 %q 剩余量为零，不能再分装", ErrConflict, parentID)
243		}
244		if total > parent.Remaining {
245			return nil, fmt.Errorf("%w: 子样总量 %s 毫升超过样品 %q 的剩余量 %s 毫升",
246				ErrConflict, formatUnits(total), parentID, formatUnits(parent.Remaining))
247		}
248	
249		candidate := s.data.deepCopy()
250		cpParent := candidate.Samples[parentID]
251		now := s.now().UTC()
252	
253		childIDs := make([]string, 0, len(parsed))
254		for _, p := range parsed {
255			childIDs = append(childIDs, p.id)
256			candidate.Samples[p.id] = &sampleRecord{
257				ID:        p.id,
258				ParentID:  parentID,
259				Initial:   p.qty,
260				Remaining: p.qty,
261				Holder:    cpParent.Holder,
262				Location:  cpParent.Location,
263				Children:  []string{},
264				History: []historyRecord{{
265					Kind:     "split",
266					Time:     now,
267					Holder:   cpParent.Holder,
268					Location: cpParent.Location,
269					Detail:   fmt.Sprintf("由样品 %s 分装", parentID),
270				}},
271			}
272		}
273		cpParent.Remaining -= total
274		cpParent.Children = append(cpParent.Children, childIDs...)
275		cpParent.History = append(cpParent.History, historyRecord{
276			Kind:     "split",
277			Time:     now,
278			Holder:   cpParent.Holder,
279			Location: cpParent.Location,
280			Detail:   fmt.Sprintf("分装创建子样 %s", strings.Join(childIDs, ", ")),
281		})
282	
283		if err := s.commit(candidate); err != nil {
284			return nil, err
285		}
286		return buildSampleView(cpParent, candidate), nil
287	}
288	
289	// HandoverInput 是发起交接（交出）的入参。
290	type HandoverInput struct {
291		// TransferID 为本次交接编号，在本地数据中唯一，去空白后非空。
292		TransferID string
293		// SampleID 为要交出的样品编号。
294		SampleID string
295		// FromHolder 为交出人，必须与样品当前持有人完全一致（比较前对入参去空白）。
296		FromHolder string
297		// FromLocation 为交出地点，必须与样品当前地点完全一致。
298		FromLocation string
299		// ToHolder 为指定接收人，不能与交出人相同。
300		ToHolder string
301		// ToLocation 为目的地点。
302		ToLocation string
303		// HandedOverAt 为交出时间。
304		HandedOverAt time.Time
305	}
306	
307	// Handover 发起一次交接：转移该样品的全部剩余量，交接进入待确认状态，
308	// 原持有人和地点保持不变，直到指定接收人在目的地点确认。
309	//
310	// 交接编号已存在时：内容（样品、人员、地点、时间）完全一致则原样返回
311	// 既有交接（无论是否已确认）；任一内容不同则拒绝。
312	func (s *Store) Handover(in HandoverInput) (*TransferView, error) {
313		s.mu.Lock()
314		defer s.mu.Unlock()
315	
316		transferID, err := trimRequired("交接编号", in.TransferID)
317		if err != nil {
318			return nil, err
319		}
320		sampleID, err := trimRequired("样品编号", in.SampleID)
321		if err != nil {
322			return nil, err
323		}
324		fromHolder, err := trimRequired("交出人", in.FromHolder)
325		if err != nil {
326			return nil, err
327		}
328		fromLocation, err := trimRequired("交出地点", in.FromLocation)
329		if err != nil {
330			return nil, err
331		}
332		toHolder, err := trimRequired("接收人", in.ToHolder)
333		if err != nil {
334			return nil, err
335		}
336		toLocation, err := trimRequired("目的地点", in.ToLocation)
337		if err != nil {
338			return nil, err
339		}
340		if in.HandedOverAt.IsZero() {
341			return nil, fmt.Errorf("%w: 交出时间不能为空", ErrInvalid)
342		}
343		handedAt := in.HandedOverAt.UTC()
344	
345		if existing, ok := s.data.Transfers[transferID]; ok {
346			if !sameHandoverRequest(existing, sampleID, fromHolder, fromLocation, toHolder, toLocation, handedAt) {
347				return nil, fmt.Errorf("%w: 交接编号 %q 已被内容不同的交接使用", ErrConflict, transferID)
348			}
349			// 完全相同的重复提交：返回原交接，不增加任何记录。
350			return buildTransferView(existing), nil
351		}
352	
353		sample, ok := s.data.Samples[sampleID]
354		if !ok {
355			return nil, fmt.Errorf("%w: 样品 %q 不存在", ErrNotFound, sampleID)
356		}
357		if sample.Remaining == 0 {
358			return nil, fmt.Errorf("%w: 样品 %q 剩余量为零，不能发起交接", ErrConflict, sampleID)
359		}
360		if sample.PendingID != "" {
361			return nil, fmt.Errorf("%w: 样品 %q 已存在待确认交接 %s",
362				ErrConflict, sampleID, sample.PendingID)
363		}
364		if sample.Holder != fromHolder {
365			return nil, fmt.Errorf("%w: 交出人 %q 与样品 %q 当前持有人 %q 不一致",
366				ErrInvalid, fromHolder, sampleID, sample.Holder)
367		}
368		if sample.Location != fromLocation {
369			return nil, fmt.Errorf("%w: 交出地点 %q 与样品 %q 当前地点 %q 不一致",
370				ErrInvalid, fromLocation, sampleID, sample.Location)
371		}
372		if toHolder == fromHolder {
373			return nil, fmt.Errorf("%w: 接收人不能与交出人 %q 相同", ErrInvalid, fromHolder)
374		}
375	
376		candidate := s.data.deepCopy()
377		rec := &transferRecord{
378			ID:           transferID,
379			SampleID:     sampleID,
380			FromHolder:   fromHolder,
381			FromLocation: fromLocation,
382			ToHolder:     toHolder,
383			ToLocation:   toLocation,
384			Qty:          sample.Remaining,
385			HandedOverAt: handedAt,
386		}
387		candidate.Transfers[transferID] = rec
388		cpSample := candidate.Samples[sampleID]
389		cpSample.PendingID = transferID
390		cpSample.History = append(cpSample.History, historyRecord{
391			Kind:     "transfer-out",
392			Time:     handedAt,
393			Holder:   fromHolder,
394			Location: fromLocation,
395			Detail:   fmt.Sprintf("发起交接 %s，待 %s 在 %s 接收", transferID, toHolder, toLocation),
396		})
397	
398		if err := s.commit(candidate); err != nil {
399			return nil, err
400		}
401		return buildTransferView(rec), nil
402	}
403	
404	// sameHandoverRequest 判断已存交接与本次请求的内容是否完全相同。
405	func sameHandoverRequest(t *transferRecord, sampleID, fromHolder, fromLocation, toHolder, toLocation string, handedAt time.Time) bool {
406		return t.SampleID == sampleID &&
407			t.FromHolder == fromHolder &&
408			t.FromLocation == fromLocation &&
409			t.ToHolder == toHolder &&
410			t.ToLocation == toLocation &&
411			t.HandedOverAt.Equal(handedAt)
412	}
413	
414	// ConfirmInput 是确认接收的入参。
415	type ConfirmInput struct {
416		// TransferID 为待确认的交接编号。
417		TransferID string
418		// Receiver 为实际接收人，必须是发起时指定的接收人。
419		Receiver string
420		// AtLocation 为接收地点，必须是发起时的目的地点。
421		AtLocation string
422		// ReceivedAt 为接收时间，不能早于交出时间。
423		ReceivedAt time.Time
424	}
425	
426	// Confirm 由指定接收人在目的地点确认接收。确认后样品的持有人和地点
427	// 才真正改变，待确认状态结束。
428	//
429	// 对已确认交接重复提交完全相同的接收信息（接收人、地点、时间）时，
430	// 返回原结果且不增加转手记录；信息不同则拒绝。
431	func (s *Store) Confirm(in ConfirmInput) (*TransferView, error) {
432		s.mu.Lock()
433		defer s.mu.Unlock()
434	
435		transferID, err := trimRequired("交接编号", in.TransferID)
436		if err != nil {
437			return nil, err
438		}
439		receiver, err := trimRequired("接收人", in.Receiver)
440		if err != nil {
441			return nil, err
442		}
443		atLocation, err := trimRequired("接收地点", in.AtLocation)
444		if err != nil {
445			return nil, err
446		}
447		if in.ReceivedAt.IsZero() {
448			return nil, fmt.Errorf("%w: 接收时间不能为空", ErrInvalid)
449		}
450		receivedAt := in.ReceivedAt.UTC()
451	
452		rec, ok := s.data.Transfers[transferID]
453		if !ok {
454			// 明确的不存在错误，绝不顺带创建交接。
455			return nil, fmt.Errorf("%w: 交接 %q 不存在", ErrNotFound, transferID)
456		}
457	
458		if rec.Confirmed {
459			same := rec.ConfirmedBy == receiver &&
460				rec.ToLocation == atLocation &&
461				rec.ReceivedAt != nil && rec.ReceivedAt.Equal(receivedAt)
462			if !same {
463				return nil, fmt.Errorf("%w: 交接 %q 已确认，接收信息与原确认不一致", ErrConflict, transferID)
464			}
465			return buildTransferView(rec), nil
466		}
467	
468		if receiver != rec.ToHolder {
469			return nil, fmt.Errorf("%w: 只有指定接收人 %q 能确认交接 %q，实际确认人为 %q",
470				ErrConflict, rec.ToHolder, transferID, receiver)
471		}
472		if atLocation != rec.ToLocation {
473			return nil, fmt.Errorf("%w: 必须在目的地点 %q 确认交接 %q，实际地点为 %q",
474				ErrConflict, rec.ToLocation, transferID, atLocation)
475		}
476		if receivedAt.Before(rec.HandedOverAt) {
477			return nil, fmt.Errorf("%w: 接收时间不能早于交出时间 %s",
478				ErrInvalid, rec.HandedOverAt.Format(time.RFC3339))
479		}
480	
481		candidate := s.data.deepCopy()
482		cp := candidate.Transfers[transferID]
483		cp.Confirmed = true
484		cp.ConfirmedBy = receiver
485		receivedAtCopy := receivedAt
486		cp.ReceivedAt = &receivedAtCopy
487	
488		sample := candidate.Samples[cp.SampleID]
489		sample.Holder = receiver
490		sample.Location = atLocation
491		sample.PendingID = ""
492		sample.History = append(sample.History, historyRecord{
493			Kind:     "transfer-in",
494			Time:     receivedAt,
495			Holder:   receiver,
496			Location: atLocation,
497			Detail:   fmt.Sprintf("交接 %s 确认接收（交出时间 %s）", transferID, cp.HandedOverAt.Format(time.RFC3339)),
498		})
499	
500		if err := s.commit(candidate); err != nil {
501			return nil, err
502		}
503		return buildTransferView(cp), nil
504	}
505	
506	// GetSample 按样品编号查询：返回来源关系、初始量/剩余量、当前持有人和
507	// 地点、直接子样、按发生顺序排列的保管历史，以及待确认交接详情。
508	// 样品不存在时返回包装了 ErrNotFound 的错误，不会创建任何记录。
509	func (s *Store) GetSample(id string) (*Sample, error) {
510		s.mu.Lock()
511		defer s.mu.Unlock()
512	
513		sampleID, err := trimRequired("样品编号", id)
514		if err != nil {
515			return nil, err
516		}
517		rec, ok := s.data.Samples[sampleID]
518		if !ok {
519			return nil, fmt.Errorf("%w: 样品 %q 不存在", ErrNotFound, sampleID)
520		}
521		return buildSampleView(rec, s.data), nil
522	}
523	
524	// GetTransfer 按交接编号查询交接详情（待确认或已确认）。
525	// 交接不存在时返回包装了 ErrNotFound 的错误，不会创建任何记录。
526	func (s *Store) GetTransfer(id string) (*TransferView, error) {
527		s.mu.Lock()
528		defer s.mu.Unlock()
529	
530		transferID, err := trimRequired("交接编号", id)
531		if err != nil {
532			return nil, err
533		}
534		rec, ok := s.data.Transfers[transferID]
535		if !ok {
536			return nil, fmt.Errorf("%w: 交接 %q 不存在", ErrNotFound, transferID)
537		}
538		return buildTransferView(rec), nil
539	}
540	
541	// buildSampleView 把内部样品记录转换为对外视图，数量统一格式化为三位小数。
542	func buildSampleView(r *sampleRecord, l *ledger) *Sample {
543		children := append([]string{}, r.Children...)
544		history := make([]History, 0, len(r.History))
545		for _, h := range r.History {
546			history = append(history, History{
547				Kind:     h.Kind,
548				Time:     h.Time,
549				Holder:   h.Holder,
550				Location: h.Location,
551				Detail:   h.Detail,
552			})
553		}
554		v := &Sample{
555			ID:         r.ID,
556			ParentID:   r.ParentID,
557			InitialQty: formatUnits(r.Initial),
558			Remaining:  formatUnits(r.Remaining),
559			Holder:     r.Holder,
560			Location:   r.Location,
561			Children:   children,
562			History:    history,
563		}
564		if r.PendingID != "" {
565			if t, ok := l.Transfers[r.PendingID]; ok {
566				v.PendingTransfer = buildTransferView(t)
567			}
568		}
569		return v
570	}
571	
572	// buildTransferView 把内部交接记录转换为对外视图。
573	func buildTransferView(r *transferRecord) *TransferView {
574		v := &TransferView{
575			TransferID:   r.ID,
576			SampleID:     r.SampleID,
577			FromHolder:   r.FromHolder,
578			FromLocation: r.FromLocation,
579			ToHolder:     r.ToHolder,
580			ToLocation:   r.ToLocation,
581			Qty:          formatUnits(r.Qty),
582			HandedOverAt: r.HandedOverAt,
583			Confirmed:    r.Confirmed,
584			ConfirmedBy:  r.ConfirmedBy,
585		}
586		if r.ReceivedAt != nil {
587			rx := *r.ReceivedAt
588			v.ReceivedAt = &rx
589			v.ConfirmedAt = r.ToLocation
590		}
591		return v
592	}
593

