package custody

import (
	"fmt"
	"regexp"
	"strconv"
	"strings"
)

// mlScale 是数量的定点刻度：所有数量以千分之一毫升为单位的整数保存。
// 合法输入最多三位小数，因此登记、分装扣减与汇总都是精确的整数运算，
// 不会因浮点舍入多出或丢失样品。
const mlScale int64 = 1000

// 数量只接受整数部分至少一位、小数部分零到三位的十进制写法，不接受符号、
// 小数点开头或科学计数法。调用方仍需单独判断数值必须大于零。
var quantityPattern = regexp.MustCompile(`^\d+(?:\.\d{1,3})?$`)

// parseQuantity 把三位小数量（单位：毫升）解析为千分之一毫升的整数。
func parseQuantity(raw string) (int64, error) {
	s := strings.TrimSpace(raw)
	if !quantityPattern.MatchString(s) {
		return 0, fmt.Errorf("%w: 数量 %q 必须是大于零且最多三位小数的十进制毫升数", ErrInvalid, raw)
	}

	wholePart := s
	fracPart := ""
	if dot := strings.IndexByte(s, '.'); dot >= 0 {
		wholePart = s[:dot]
		fracPart = s[dot+1:]
	}

	whole, err := strconv.ParseInt(wholePart, 10, 64)
	if err != nil {
		return 0, fmt.Errorf("%w: 数量 %q 超出可表示范围", ErrInvalid, raw)
	}
	for len(fracPart) < 3 {
		fracPart += "0"
	}
	frac, err := strconv.ParseInt(fracPart, 10, 64)
	if err != nil {
		return 0, fmt.Errorf("%w: 数量 %q 超出可表示范围", ErrInvalid, raw)
	}

	units := whole*mlScale + frac
	if units <= 0 {
		return 0, fmt.Errorf("%w: 数量 %q 必须大于零", ErrInvalid, raw)
	}
	if units/mlScale != whole {
		return 0, fmt.Errorf("%w: 数量 %q 超出可表示范围", ErrInvalid, raw)
	}
	return units, nil
}

// formatUnits 把内部整数数量统一渲染为三位小数的毫升字符串。
func formatUnits(units int64) string {
	if units < 0 {
		return "-" + formatUnits(-units)
	}
	return fmt.Sprintf("%d.%03d", units/mlScale, units%mlScale)
}

// trimRequired 去掉首尾空白，并要求结果非空。
func trimRequired(field, raw string) (string, error) {
	v := strings.TrimSpace(raw)
	if v == "" {
		return "", fmt.Errorf("%w: %s去掉首尾空白后不能为空", ErrInvalid, field)
	}
	return v, nil
}

// Package custody 是本地样品流转与保管链。
//
// 一份本地样品数据由 [Store] 表示，通过 [Open] 创建或重新打开；所有
// 登记、分装、交接与查询都通过 Store 的公开方法完成。数据以 JSON
// 原子落盘，关闭后用同一文件路径重新 [Open] 即可恢复全部样品、保管
// 历史以及交接编号的重复提交判断。
//
// 数量以毫升为单位，只接受大于零、最多三位小数的十进制输入；内部按
// 千分之一毫升的整数精确运算，查询时统一显示三位小数，分装扣减不会
// 因舍入多出或丢失样品。
//
// 典型流程：
//
//	s, err := custody.Open("sample-data.json")
//	// 登记原样
//	s.Register(custody.RegisterInput{ID: "S-001", Qty: "10.000", Holder: "张三", Location: "实验室A"})
//	// 一次分装创建多个子样（任一子样不合法则整次不生效）
//	s.Split(custody.SplitInput{ParentID: "S-001", Parts: []custody.SplitPart{
//		{ID: "S-001-A", Qty: "4.000"},
//		{ID: "S-001-B", Qty: "6.000"},
//	}})
//	// 发起交接，随后由指定接收人在目的地点确认
//	s.Handover(custody.HandoverInput{
//		TransferID: "TR-001", SampleID: "S-001-A",
//		FromHolder: "张三", FromLocation: "实验室A",
//		ToHolder: "李四", ToLocation: "实验室B",
//		HandedOverAt: handoverTime,
//	})
//	s.Confirm(custody.ConfirmInput{TransferID: "TR-001", Receiver: "李四", AtLocation: "实验室B", ReceivedAt: receiveTime})
//	// 查询
//	view, _ := s.GetSample("S-001")
//	transfer, _ := s.GetTransfer("TR-001")
package custody

// Ready 表示基线可以运行。
func Ready() bool { return true }

